using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
namespace kok {
 internal static class ClipTools {
  static void Source(AgentAction action,Func<string,bool> exists){CapabilitySchema.Check(CapabilitySchema.Obj(AgentRules.Tools.First(t=>t.Name==action.tool).Properties,AgentRules.Tools.First(t=>t.Name==action.tool).Required),action.args);if(action.args.ContainsKey("id")&&!exists(Convert.ToString(action.args["id"])))throw new FormatException("unknown or out-of-scope source");if(action.args.ContainsKey("ids"))foreach(var id in AgentTaskState.Get<List<string>>(action.args,"ids"))if(!exists(id))throw new FormatException("unknown or out-of-scope source");}
  public static AgentToolSpec[] Tools(){return new[]{
   new AgentToolSpec{Name="read_clips",Title="读取摘录",Requires=Need.NormalLibrary,Properties=AgentRules.Props("ids",AgentRules.Arr("Source file IDs in the allowed scope",24,AgentRules.Id)),Required=new[]{"ids"},Description="Read saved clips for selected source files, including their source anchors.",Signature="read_clips{ids}",Validate=Source,Read=(lib,state,call,token)=>{var ids=AgentTaskState.Get<List<string>>(call.args,"ids");var rows=((WorkspaceState)lib.WorkspaceSnapshot()).clips.Where(c=>ids.Contains(c.source.itemId)).Take(100).ToList();return Task.FromResult(new Dictionary<string,object>{{"text",Library.Json.Serialize(rows)}});}},
   new AgentToolSpec{Name="create_clip",Title="创建摘录",CapabilityId="workspace.createClip",Requires=Need.NormalLibrary,Write=true,Properties=AgentRules.Props("id",AgentRules.Id,"title",AgentRules.Str("Short clip title",200),"text",AgentRules.Str("Quoted content or a thought",20000),"time",new Dictionary<string,object>{{"type","number"},{"minimum",0},{"maximum",864000}},"endTime",new Dictionary<string,object>{{"type","number"},{"minimum",0},{"maximum",864000}}),Required=new[]{"id","title","text"},Description="PROPOSE a source-linked clip. The user must approve it.",Signature="create_clip{id,title,text,time?,endTime?}",Validate=Source,Execute=(lib,state,call,token)=>{string source=Convert.ToString(call.args["id"]);double time=call.args.ContainsKey("time")?Convert.ToDouble(call.args["time"]):0,end=call.args.ContainsKey("endTime")?Convert.ToDouble(call.args["endTime"]):time;var clip=new ClipRecord{id=call.id,title=Convert.ToString(call.args["title"]),text=Convert.ToString(call.args["text"]),created=DateTime.UtcNow.ToString("o"),source=new SourceAnchor{itemId=source,text=Convert.ToString(call.args["text"]),time=time,endTime=end}};var op=lib.ProposeResource("clip",clip.id,Library.Json.Serialize(clip),"agent:"+state.id,call.id);lib.OperationApply(op.id,true);return new AgentToolReceipt{result=new Dictionary<string,object>{{"text","Clip created"},{"clipId",clip.id},{"id",source}}};}},
   new AgentToolSpec{Name="write_from_clips",Title="用摘录写稿",Requires=Need.NormalLibrary,Write=true,Properties=AgentRules.Props("ids",AgentRules.Arr("Allowed source file IDs",24,AgentRules.Id),"clips",AgentRules.Arr("Saved clip IDs returned by read_clips",50,AgentRules.Id),"name",AgentRules.Str("Document name",100)),Required=new[]{"ids","clips","name"},Description="PROPOSE a Markdown document assembled from saved clips with links to source files.",Signature="write_from_clips{ids,clips,name}",Validate=Source,Execute=(lib,state,call,token)=>{var ids=AgentTaskState.Get<List<string>>(call.args,"ids");var wanted=AgentTaskState.Get<List<string>>(call.args,"clips");var rows=((WorkspaceState)lib.WorkspaceSnapshot()).clips.Where(c=>wanted.Contains(c.id)&&ids.Contains(c.source.itemId)).ToList();if(rows.Count!=wanted.Distinct().Count())throw new InvalidOperationException("摘录超出当前资料范围。");string text=String.Join("\n\n",rows.Select(c=>"## "+c.title+"\n\n"+c.text+"\n\n[["+c.source.itemId+"]]").ToArray());var e=lib.CreateDocument(Convert.ToString(call.args["name"]),"md","",text,call.id,"agent:"+state.id);return new AgentToolReceipt{result=new Dictionary<string,object>{{"id",e.id},{"name",e.name},{"text","Document created from clips"}},stamp=lib.AgentCreatedStamp(e.id)};}}
  };}
 }
}
